1	import { describe, it, expect } from "vitest";
2	import { nextGeneration } from "./game-of-life.js";
3	
4	describe("Game of Life - Next Generation", () => {
5	  it("should return an empty grid for a single live cell with no neighbors", () => {
6	    expect(nextGeneration([[0, 0]])).toEqual([]);
7	  });
8	  it("should return an empty grid for two adjacent cells that each have one neighbor", () => {
9	    expect(nextGeneration([[0, 1], [1, 1]])).toEqual([]);
10	  });
11	  it("should keep a live cell with three live neighbors alive", () => {
12	    expect(nextGeneration([[0, 0], [1, 0], [2, 0], [1, 1]])).toContainEqual([
13	      1, 1,
14	    ]);
15	  });
16	  it("should kill a live cell with four live neighbors", () => {
17	    expect(
18	      nextGeneration([
19	        [1, 1],
20	        [0, 0],
21	        [0, 1],
22	        [0, 2],
23	        [1, 0],
24	      ]),
25	    ).not.toContainEqual([1, 1]);
26	  });
27	  it.todo("should bring a dead cell with exactly three live neighbors to life");
28	  it.todo("should turn a vertical blinker into a horizontal blinker");
29	  it.todo("should turn a horizontal blinker back into a vertical blinker");
30	  it.todo("should leave a block unchanged");
31	  it.todo("should compute the next generation for cells at negative coordinates");
32	});
33

1	export type Cell = [number, number];
2	
3	const isNeighbor = ([x1, y1]: Cell, [x2, y2]: Cell): boolean =>
4	  Math.abs(x1 - x2) <= 1 && Math.abs(y1 - y2) <= 1 && !(x1 === x2 && y1 === y2);
5	
6	const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
7	  liveCells.filter((other) => isNeighbor(cell, other)).length;
8	
9	export const nextGeneration = (liveCells: Cell[]): Cell[] =>
10	  liveCells.filter((cell) => countLiveNeighbors(cell, liveCells) === 3);
